function answerSuggestion(question, product) {
  const text = question.text.toLowerCase();
  let suggested = "Hola. \xBFQu\xE9 cantidad y presentaci\xF3n necesit\xE1s? Podemos revisar la opci\xF3n correspondiente.";
  const evidence = [];
  if (/env[ií]o|entrega|flete|provincia/.test(text)) {
    suggested = "Hola. \xBFEn qu\xE9 localidad necesit\xE1s recibir el pedido? Tenemos reparto local y podemos entregar sin cargo en agencias de La Boca/Barracas para coordinar el transporte a tu regi\xF3n.";
    evidence.push("Pol\xEDtica de entregas confirmada por el administrador");
  } else if (/stock|disponib|cantidad/.test(text)) {
    suggested = "Hola. Indicanos la cantidad y medida que necesit\xE1s para confirmar disponibilidad y coordinar la entrega.";
    evidence.push("Disponibilidad f\xEDsica requiere confirmaci\xF3n");
  } else if (product?.unit === "barra" && product.length && /largo|longitud|metros|medida/.test(text)) {
    suggested = `Hola. La presentaci\xF3n indicada para este producto es una barra de ${product.length} metros. \xBFQu\xE9 cantidad necesit\xE1s?`;
    evidence.push("Presentaci\xF3n identificada en el t\xEDtulo: " + product.name);
  } else if (product?.unit === "hoja" && /hoja|unidad|presenta/.test(text)) {
    suggested = "Hola. Este producto se comercializa por hoja. \xBFQu\xE9 cantidad necesit\xE1s?";
    evidence.push("Regla de presentaci\xF3n por familia aprobada");
  }
  return { suggested, evidence, warnings: ["Revisar antes de enviar. No confirma stock f\xEDsico, precio ni fecha de entrega."], engine: "reglas_con_fuentes" };
}
