    if (String(q.seller_id) !== await sellerId(db) || q.item_id !== p.item_id) throw new Problem("No se pudo verificar la pertenencia", 403);
    if (q.status !== "ANSWERED" || q.answer?.text !== p.text) throw new Problem("La lectura no confirma el resultado esperado. Revis\xE1 Mercado Libre; no se reenviar\xE1.", 409);
